import { serve } from "https://deno.land/std@0.190.0/http/server.ts";

const PDF_B64 = "";

serve(async () => {
  const key = Deno.env.get("RESEND_API_KEY");
  const html = `
  <div style="font-family:Arial,sans-serif;color:#0f2145;line-height:1.6">
    <h2 style="color:#0f2145">Ordrebekreftelse - KS Bygg</h2>
    <p>Hei Viktor,</p>
    <p>Vedlagt finner du ordrebekreftelsen for <strong>Fasadeteknikk AS</strong>.</p>
    <ul>
      <li>Modul: KS Bygg (IK_BYGG)</li>
      <li>Bestilt av: Kent Aleksander Karlsen (post@fasade-teknikk.no)</li>
      <li>Dato: 04.05.2026 kl. 13:34</li>
      <li>Pris: 799,- pr. mnd eks. mva</li>
      <li>Vilk&#229;r akseptert: Ja</li>
    </ul>
    <p>Med vennlig hilsen<br/>Total-IK</p>
  </div>`;

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      from: "Total-IK <noreply@totalik.no>",
      to: ["viktor@athenahms.no"],
      subject: "Ordrebekreftelse - KS Bygg - Fasadeteknikk AS",
      html,
      attachments: [{ filename: "Ordrebekreftelse-Fasadeteknikk-AS-KS-Bygg.pdf", content: PDF_B64 }],
    }),
  });
  const out = await res.text();
  return new Response(out, { status: res.status, headers: { "Content-Type": "application/json" } });
});
